#!/usr/bin/env node
/**
 * PDF Extraction V3 · E12 — generated-corpus runner.
 *
 * Thin wrapper that runs the real browser/export generated-corpus e2e (the
 * end-to-end proof) via Playwright and the pure release suites via Vitest. Exits
 * nonzero if either fails. Cleans no repository files (generated bytes stay
 * in-memory in the e2e). This runner never contacts a network provider.
 */
import { spawnSync } from 'node:child_process';

function run(cmd, args, label) {
  process.stderr.write(`\n▶ ${label}\n`);
  return spawnSync(cmd, args, { stdio: 'inherit' }).status ?? 1;
}

const pure = run('npx', ['vitest', 'run', 'src/lib/reportTemplate/ingestion/releaseV3/__tests__'], 'pure release suites');
const e2e = run('npx', ['playwright', 'test', '--config=playwright.config.ts', 'tests-e2e/pdf-extraction-v3'], 'real generated-corpus e2e');

const ok = pure === 0 && e2e === 0;
console.log(`\ngenerated-corpus: ${ok ? 'PASS' : 'FAIL'} (pure=${pure === 0} e2e=${e2e === 0})`);
process.exit(ok ? 0 : 1);
